import{_ as e,a,b as o,c as r,d as i,e as n,f as s,g as p}from"./chunks/image8.CpjXVgYC.js";import{_ as l,o as c,c as u,ag as m}from"./chunks/framework.D9ghT4bC.js";const I=JSON.parse('{"title":"Unciv Multiplayer Tutorial","description":"","frontmatter":{},"headers":[],"relativePath":"Community/Guides/Multiplayer-tutorial/index.md","filePath":"Community/Guides/Multiplayer-tutorial/index.md"}'),h={name:"Community/Guides/Multiplayer-tutorial/index.md"};function d(g,t,y,q,_,v){return c(),u("div",null,[...t[0]||(t[0]=[m('<h1 id="unciv-multiplayer-tutorial" tabindex="-1">Unciv Multiplayer Tutorial <a class="header-anchor" href="#unciv-multiplayer-tutorial" aria-label="Permalink to &quot;Unciv Multiplayer Tutorial&quot;">​</a></h1><blockquote><p>Author: SpringPizazz</p><p>Date: 2024-03-27</p></blockquote><p>Before playing multiplayer, understand the UID: UID stands for User Identification. In Unciv multiplayer there are two kinds: the <strong>player ID</strong> (identifies players) and the <strong>game/room ID</strong> (identifies a match).</p><p>Players must also allow Unciv to access the clipboard (especially on Android) so the game can read/paste these UIDs.</p><p>All participants must strictly use the same game version, the same mods, and the same mod versions to avoid unknown errors.</p><h2 id="connecting-to-the-multiplayer-server" tabindex="-1">Connecting to the multiplayer server <a class="header-anchor" href="#connecting-to-the-multiplayer-server" aria-label="Permalink to &quot;Connecting to the multiplayer server&quot;">​</a></h2><p>Open the main menu, click &quot;Options&quot;,</p><p><img src="'+e+'" alt="Connect to server - step 1"></p><p>Click &quot;Multiplayer&quot; on top,</p><p><img src="'+a+'" alt="Connect to server - step 2"></p><p>Enter the server address: <a href="http://sp.unciv.cn:30123" target="_blank" rel="noreferrer">http://sp.unciv.cn:30123</a></p><p><img src="'+o+'" alt="Connect to server - step 3"></p><p>Set the sync frequency as shown above,</p><p>Set a password (default is 123456) to prevent others from impersonating your player ID and disturbing your games,</p><p>Click &quot;Check server connection&quot; — a &quot;Success!&quot; popup should appear,</p><p><img src="'+r+'" alt="Connect to server - step 4"></p><p>Exit Unciv (kill background processes), reopen it, return to the same screen and click &quot;Check server connection&quot; again. If it still says &quot;Success!&quot;, you&#39;ve successfully connected to the server!</p><h2 id="getting-your-player-id" tabindex="-1">Getting your player ID <a class="header-anchor" href="#getting-your-player-id" aria-label="Permalink to &quot;Getting your player ID&quot;">​</a></h2><p>Back at the main menu, click &quot;Multiplayer&quot;,</p><p>Click &quot;Copy player ID&quot;,</p><p><img src="'+i+'" alt="Get player ID"></p><p>Your player ID is now on the clipboard!</p><p>If you&#39;re hosting, keep your player ID; if you&#39;re joining, send this player ID to the host via social media (e.g. QQ), stating clearly that it&#39;s a player ID (not a game ID).</p><h2 id="host-creating-a-room" tabindex="-1">Host creating a room <a class="header-anchor" href="#host-creating-a-room" aria-label="Permalink to &quot;Host creating a room&quot;">​</a></h2><p>Back at the main menu, click &quot;Start new game&quot;,</p><p>Click &quot;Online multiplayer&quot;,</p><p><img src="'+n+'" alt="Host creating a room - step 1"></p><p>Paste the player ID into the corresponding text field and pick your civilization,</p><p><img src="'+s+'" alt="Host creating a room - step 2"></p><p>Choose the map settings, then click &quot;Start game!&quot; at the bottom right. When you reach the game screen, the room ID is automatically saved to your clipboard — send it to all participants, stating clearly that it&#39;s a room ID, not a player ID.</p><h2 id="participants-joining-a-room" tabindex="-1">Participants joining a room <a class="header-anchor" href="#participants-joining-a-room" aria-label="Permalink to &quot;Participants joining a room&quot;">​</a></h2><p>Copy the host&#39;s room ID to your clipboard,</p><p>Back at the main menu, click &quot;Multiplayer&quot;,</p><p>Click &quot;Add multiplayer game&quot;,</p><p><img src="'+p+'" alt="Participant joining - step 1"></p><p>Paste the room ID in the first text field; enter your note for this game in the second field (leave empty and it&#39;s overwritten by the room ID).</p><p>After entering, click &quot;Save game&quot; at the bottom right, return to the previous page, click the button showing your note, and click &quot;Start game&quot; at the bottom right to join the match.</p>',37)])])}const b=l(h,[["render",d]]);export{I as __pageData,b as default};
